// 899371 P8 (docs/enterprise-899371-learning-plan.md §21) — «جرّب الكود»: running a C# program of a learning book in the Reader.
// This module is the PURE part (no request, no storage): the course's run index, the wrap rule, the limits and the body parser.
//   • The RUN INDEX (api/src/data/learning-run/<courseId>.json, generated by scripts/build-learning-run-index.mjs) lists the C#
//     blocks a learner may run: book programs with a `Main`, each PROVEN to compile alone with the csharp@1 settings. An entry is
//     { moduleId, codeSha } under pages[pageId].blocks[blockId]; the code itself is not stored (the learner sends the source, which
//     they may edit), so the index only says WHERE running is allowed.
//   • The WRAP rule: the book prints `static void Main` alone; a source with no `class` declaration gets `public class Program { `
//     on its FIRST line and `}` after its last, so a compiler line number is the learner's own line number. `using System` comes
//     from the worker's GlobalUsings.cs.
//   • The LIMITS are the server's own (time, memory, output); the client never sends a limit.
const crypto = require("crypto");
const { utf8ByteLength } = require("./shared-finalization/codingQuestion");

const ID = /^[A-Za-z0-9_-]{1,64}$/;
const INDEX_CACHE = new Map();
const RUN_LANGUAGE = Object.freeze({ language: "csharp", languageVersion: 1 });
const RUN_LIMITS = Object.freeze({ timeMs: 2000, memoryMb: 128, outputBytes: 16384 });
const SOURCE_MAX_BYTES = 16 * 1024;
const STDIN_MAX_BYTES = 4 * 1024;
const BODY_MAX_CHARS = 64 * 1024;
const BODY_KEYS = ["blockId", "pageId", "source", "stdin"];
const WRAP_PREFIX = "public class Program { ";
const WRAP_SUFFIX = "\n}\n";

const cleanId = v => (typeof v === "string" ? v.trim() : "");
const codeSha = code => crypto.createHash("sha256").update(String(code), "utf8").digest("hex");

/** The course's run index, read once per process and frozen; null when the course has none (or it is malformed). */
function loadRunIndex(courseId) {
  const id = cleanId(courseId);
  if (!ID.test(id)) return null;
  if (INDEX_CACHE.has(id)) return INDEX_CACHE.get(id);
  let index = null;
  try { index = require("../data/learning-run/" + id + ".json"); } catch { index = null; }
  if (!index || index.schemaVersion !== 1 || index.courseId !== id || !index.pages || typeof index.pages !== "object" || Array.isArray(index.pages)) index = null;
  if (index) index = deepFreeze(index);
  INDEX_CACHE.set(id, index);
  return index;
}
function deepFreeze(v) { if (v && typeof v === "object") { for (const k of Object.keys(v)) deepFreeze(v[k]); Object.freeze(v); } return v; }

/** One runnable block → { moduleId }, or null (unknown page or block, or a malformed entry). Own properties only. */
function findRunBlock(index, pageId, blockId) {
  const p = cleanId(pageId), b = cleanId(blockId);
  if (!index || !ID.test(p) || !ID.test(b) || !Object.prototype.hasOwnProperty.call(index.pages, p)) return null;
  const page = index.pages[p];
  if (!page || typeof page !== "object" || !page.blocks || typeof page.blocks !== "object" || !Object.prototype.hasOwnProperty.call(page.blocks, b)) return null;
  const entry = page.blocks[b];
  const moduleId = entry && typeof entry === "object" ? cleanId(entry.moduleId) : "";
  return ID.test(moduleId) ? { moduleId } : null;
}

/** Every runnable block the `canSee(moduleId)` predicate allows → { [pageId]: [blockId, …] } (sorted, deterministic). */
function runnableBlocks(index, canSee) {
  const out = {};
  if (!index) return out;
  for (const pageId of Object.keys(index.pages).sort()) {
    const ids = Object.keys(index.pages[pageId].blocks || {}).filter(b => { const f = findRunBlock(index, pageId, b); return f && canSee(f.moduleId); }).sort();
    if (ids.length) out[pageId] = ids;
  }
  return out;
}

/** The program the runner compiles: the source as sent, wrapped in `public class Program { … }` when it declares no class. */
function wrapProgram(source) {
  const s = String(source);
  return /\bclass\s+[A-Za-z_]/.test(s) ? s : WRAP_PREFIX + s + WRAP_SUFFIX;
}

/** Strict body: exactly { pageId, blockId, source, stdin }, strings, bounded; a blank source is refused. → body | { error } */
function parseRunBody(text) {
  if (typeof text !== "string" || text.length > BODY_MAX_CHARS) return { error: "TOO_LARGE" };
  let b;
  try { b = JSON.parse(text); } catch { return { error: "REQUEST_INVALID" }; }
  if (!b || typeof b !== "object" || Array.isArray(b)) return { error: "REQUEST_INVALID" };
  const keys = Object.keys(b).sort();
  if (keys.length !== BODY_KEYS.length || keys.some((k, i) => k !== BODY_KEYS[i])) return { error: "REQUEST_INVALID" };
  const { pageId, blockId, source, stdin } = b;
  if ([pageId, blockId, source, stdin].some(v => typeof v !== "string")) return { error: "REQUEST_INVALID" };
  if (!ID.test(pageId) || !ID.test(blockId)) return { error: "REQUEST_INVALID" };
  if (utf8ByteLength(source) > SOURCE_MAX_BYTES || utf8ByteLength(stdin) > STDIN_MAX_BYTES) return { error: "TOO_LARGE" };
  if (!source.trim()) return { error: "SOURCE_EMPTY" };
  return { pageId, blockId, source, stdin };
}

module.exports = { RUN_LANGUAGE, RUN_LIMITS, SOURCE_MAX_BYTES, STDIN_MAX_BYTES, BODY_MAX_CHARS, WRAP_PREFIX, WRAP_SUFFIX, loadRunIndex, findRunBlock, runnableBlocks, wrapProgram, parseRunBody, codeSha };
